mapper.select:
SELECT tc.id, tc.card_name, tc.card_company, tc.bank_name, tc.required_account, tc.instant_use, tc.applied_rate_info, tc.exchange_fee, tc.re_exchange_fee, tc.payment_fee, tc.withdrawal_fee, tc.auto_charge_supported, tc.is_transit_card AS transit_card, ( SELECT COUNT(*) FROM travel_card_currencies tcc WHERE tcc.card_id = tc.id ) AS supported_currency_count FROM travel_cards tc WHERE tc.is_active = TRUE AND tc.id IN
#{cardId}
ORDER BY FIELD( tc.id,
#{cardId}
)
